        totals.put(accId, zero);
    }
    for (AggregateResult ar : [
        SELECT AccountId, SUM(Amount) total
        FROM Opportunity
        WHERE IsWon = true AND AccountId IN :accountIds
        GROUP BY AccountId
    ]) {
