}

public static Integer reverseDigits(Integer n) {
    Integer num = Math.abs(n);
    Integer reversed = 0;
    while (num > 0) {
        reversed = reversed * 10 + Math.mod(num, 10);
        num = num / 10;
    }
    return n < 0 ? -reversed : reversed;
}

